public sealed class PublishCommand(string exchange)
{
    public string Exchange { get; } = exchange;
    public required string RoutingKey { get; init; }
    public int RetryCount { get; init; } = 3;
}

var cmd = new PublishCommand("attempts")
{
    RoutingKey = "grading.completed"
};

public sealed class RabbitConfig
{
    public string Host { get; }
    public int Port { get; }

    public RabbitConfig(string host) : this(host, 5672) { }

    public RabbitConfig(string host, int port)
    {
        Host = host ?? throw new ArgumentNullException(nameof(host));
        Port = port is > 0 and < 65536 ? port
            : throw new ArgumentOutOfRangeException(nameof(port));
    }
}

struct Config
{
    public int TimeoutMs;
    public Config() => TimeoutMs = 5000;
}

var a = new Config();     // TimeoutMs = 5000 (ctor runs)
var b = default(Config);  // TimeoutMs = 0 (ctor skipped)
var c = new Config[3];    // each element: TimeoutMs = 0
